"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["6607"],{7735(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/kctf-2025_review","metadata":{"permalink":"/blog/kctf-2025_review","source":"@site/blog/kctf-2025_review.md","title":"2025 \uACBD\uAE30\uB300\uD559\uAD50 \uD574\uD0B9\uBC29\uC5B4\uB300\uD68C \uCD9C\uC81C \uD6C4\uAE30","description":"\uBAA8\uAD50\uC778 \uACBD\uAE30\uB300\uD559\uAD50\uC5D0\uC120 \uB9E4\uB144 \uC5F0\uB9D0\uC5D0 \uC804\uC0B0\uC815\uBCF4\uC6D0\uACFC K.Knock\uC774 \uD611\uC5C5\uD558\uC5EC \uD574\uD0B9\uBC29\uC5B4\uB300\uD68C\uB97C \uAC1C\uCD5C\uD55C\uB2E4.","date":"2025-12-30T18:00:00.000Z","tags":[{"inline":true,"label":"research","permalink":"/blog/tags/research"},{"inline":true,"label":"ctf","permalink":"/blog/tags/ctf"},{"inline":true,"label":"react2shell","permalink":"/blog/tags/react-2-shell"},{"inline":true,"label":"osint","permalink":"/blog/tags/osint"}],"readingTime":5.01,"hasTruncateMarker":true,"authors":[{"name":"SYRU","title":"security researcher","url":"https://github.com/l0vey0u","imageURL":"https://avatars.githubusercontent.com/u/30224688","key":"syru","page":null}],"frontMatter":{"title":"2025 \uACBD\uAE30\uB300\uD559\uAD50 \uD574\uD0B9\uBC29\uC5B4\uB300\uD68C \uCD9C\uC81C \uD6C4\uAE30","authors":"syru","tags":["research","ctf","react2shell","osint"],"date":"2025-12-30T18:00:00.000Z"},"unlisted":false,"nextItem":{"title":"Docusaurus \uC0BD\uC9C8 \uAE30\uB85D","permalink":"/blog/memo_docusaurus"}},"content":"\uBAA8\uAD50\uC778 \uACBD\uAE30\uB300\uD559\uAD50\uC5D0\uC120 \uB9E4\uB144 \uC5F0\uB9D0\uC5D0 \uC804\uC0B0\uC815\uBCF4\uC6D0\uACFC K.Knock\uC774 \uD611\uC5C5\uD558\uC5EC \uD574\uD0B9\uBC29\uC5B4\uB300\uD68C\uB97C \uAC1C\uCD5C\uD55C\uB2E4.\\n\\n\uB098\uB294 \uC815\uD68C\uC6D0\uC774 \uB41C \uC774\uD6C4\uB85C \uAD70 \uBCF5\uBB34 \uC2DC\uC808\uC744 \uC81C\uC678\uD558\uACE0 \uB9E4\uB144 \uBB38\uC81C\uB97C \uCD9C\uC81C\uD558\uACE0 \uC788\uB294\uB370 \uC62C\uD574\uB294 \uC6D0\uB798 XSS \uBB38\uC81C\uB97C \uB0B4\uB824\uACE0 \uD588\uB2E4.\\n\\n\uADF8\uB807\uAC8C \uC5B4\uB5A4 \uCEE8\uC149\uC73C\uB85C \uB0BC\uC9C0 \uACE0\uBBFC\uD558\uB358 \uC640\uC911\uC5D0 12\uC6D4 4\uC77C React2Shell\uC774\uB77C\uB294 \uC5C4\uCCAD\uB09C \uC0AC\uAC74\uC774 \uBC1C\uC0DD\uD574\uBC84\uB838\uB2E4.\\n\\nLog4j \uB9CC\uD55C \uD070 \uC0AC\uAC74\uC774\uC9C0\uB9CC \uC2EC\uC9C0\uC5B4 exploit\uC774 \uD6E8\uC52C \uAC04\uB2E8\uD558\uC5EC \uC774\uAC74 \uBB38\uC81C\uB85C \uAF2D \uB0B4\uC57C\uACA0\uB2E4\uACE0 \uB2E4\uC9D0\uD558\uAC8C\uB41C\uB2E4.\\n\\n\uAC70\uAE30\uC5D0 \uAC04\uB2E8\uD55C \uC810\uC218 \uC8FC\uAE30 \uBB38\uC81C \uD558\uB098 \uB354\uD574\uC11C \uB450 \uBB38\uC81C\uB97C \uCD9C\uC81C\uD558\uAC8C\uB418\uC5C8\uB2E4.\\n\\n{/* truncate */}\\n\\n## Welcome (Misc)\\n\\n> \uC2E4\uC218\uB85C \uB09C\uC774\uB3C4\uAC00 \uB354 \uB0B4\uB824\uAC00\uBC84\uB838\uB294\uB370 \uC65C \uC548 \uD480\uB9AC\uC9C0?\\n\\n### \uACB0\uACFC\\n\\n820\uC810 (7 Solves)\\n\\n### \uCD9C\uC81C \uC758\uB3C4\\n\\n\uC694\uC998 \uBAA8\uC758\uD574\uD0B9 \uC5C5\uBB34\uB97C \uC218\uD589\uD558\uB2E4\uBCF4\uBA74 \uC804\uD1B5\uC801\uC778 \uCDE8\uC57D\uC810\uC758 \uBC1C\uACAC \uBE48\uB3C4\uAC00 \uB9CE\uC774 \uB0AE\uC544\uC9C4\uAC8C \uB290\uAEF4\uC9C4\uB2E4.\\n\\n\uADF8\uB798\uB3C4 \uB6AB\uC5B4\uC57C\uD55C\uB2E4\uB294 \uB9C8\uC74C\uAC00\uC9D0\uC73C\uB85C \uB2E4\uC591\uD55C \uBC29\uD5A5\uC73C\uB85C \uD30C\uACE0\uB4E4\uB2E4\uBCF4\uBA74 OSINT \uAE30\uBC95\uC744 \uD65C\uC6A9\uD558\uAC8C \uB418\uB294\uB370 \uB098\uB294 \uADF8 \uC911\uC5D0\uC11C \uAE43\uD5C8\uBE0C\uB97C \uD65C\uC6A9\uD55C \uC815\uBCF4 \uD0D0\uC0C9\uC744 \uCC38 \uC560\uC6A9\uD55C\uB2E4.\\n\\n\uADF8\uB798\uC11C \uB0B4 \uD3EC\uD2B8\uD3F4\uB9AC\uC624 \uC0AC\uC774\uD2B8 \uB0B4 \uC228\uC5B4\uC788\uB294 \uD50C\uB798\uADF8\uB97C \uCC3E\uC544\uBCF4\uB3C4\uB85D \uBB38\uC81C\uB97C \uB0B4\uC5C8\uB2E4.\\n\\n### \uC758\uB3C4\uD55C \uD480\uC774 \uBC29\uD5A5\\n\\n1. \uD3EC\uD2B8\uD3F4\uB9AC\uC624 \uC0AC\uC774\uD2B8 \uC811\uADFC \uD6C4 \uC18C\uC2A4\uCF54\uB4DC \uD655\uC778 (`view-source:https://leak.syru.dev` or DevTools)\\n2. Docusaurus \uC0AC\uC6A9\uD558\uC5EC \uC81C\uC791\uB41C \uC0AC\uC774\uD2B8\uC784\uC744 \uD30C\uC545\\n     ```html\\n     <meta name=\\"generator\\" content=\\"Docusaurus v2.3.0\\">\\n     ```\\n3. Docusaurus\uC5D0 \uB300\uD574 \uCC3E\uC544\uBCF4\uACE0 \uC815\uC801 \uC0AC\uC774\uD2B8 \uC0DD\uC131\uAE30\uB77C\uB294 \uC815\uBCF4\uB97C \uD655\uC778\\n4. \uC815\uC801 \uC0AC\uC774\uD2B8\uC5D0 \uB300\uD574 \uCC3E\uC544\uBCF4\uACE0 \uAE43\uD5C8\uBE0C\uB97C \uD1B5\uD574 \uBC30\uD3EC\uD558\uB294 \uBC29\uBC95 \uD655\uC778\\n5. \uAE43\uD5C8\uBE0C \uAC80\uC0C9 \uAE30\uB2A5\uC744 \uD1B5\uD574 `leak.syru.dev`\uB97C \uAC80\uC0C9\uD558\uC5EC \uC815\uC801 \uC0AC\uC774\uD2B8 \uBC30\uD3EC\uC911\uC778 \uB9AC\uD3EC\uC9C0\uD1A0\uB9AC \uBC1C\uACAC\\n    - `https://github.com/l0vey0u/l0vey0u.github.io`\\n6. \uB9AC\uD3EC\uC9C0\uD1A0\uB9AC \uD655\uC778 \uC911 **2048**\uC774\uB780 \uC218\uC0C1\uD55C \uACBD\uB85C \uBC1C\uACAC (\uC0AC\uC774\uD2B8 \uB2E8\uC21C \uD0D0\uC0C9\uC73C\uB860 \uBC1C\uACAC \uBD88\uAC00)\\n7. `https://leak.syru.dev/2048`\uB85C \uC811\uADFC, 2048 \uAC8C\uC784 \uD655\uC778\\n8. \uC18C\uC2A4\uCF54\uB4DC \uD655\uC778 \uD6C4 \uC8FC\uC11D \uCC98\uB9AC\uB41C \uD50C\uB798\uADF8 \uD655\uC778\\n\\n\\n### \uC5EC\uB2F4\\n\\n\uAE43\uD5C8\uBE0C\uB97C \uCC3E\uB294\uAC8C \uAC00\uC7A5 \uC911\uC694\uD55C \uBB38\uC81C\uC600\uB294\uB370 \uB0B4 \uD3EC\uD3F4\uC5D0 \uAE43\uD5C8\uBE0C \uB9C1\uD06C\uAC00 \uC8FC\uC5B4\uC838\uC788\uB2E4\uB294 \uAC83\uC744 \uC78A\uC5B4\uBC84\uB838\uB2E4,,,\\n\\n\uCC98\uC74C\uC5D0 `/2048`\uC744 \uD78C\uD2B8\uB85C \uC124\uC815\uD588\uB2E4\uAC00 \uB108\uBB34 \uC758\uBBF8\uAC00 \uC5C6\uB294 \uBB38\uC81C\uAC00 \uB420 \uAC83 \uAC19\uC544 `#osint #github`\uB85C \uBC14\uAFB8\uC5C8\uB294\uB370 \uB2E4\uC218\uC758 \uD480\uC774 \uBC29\uD5A5\uC774 `Junior developer\'s mistake`\uBB38\uC81C\uC640 \uB3D9\uC77C\uD558\uAC8C \uB418\uC5B4 \uC7AC\uBBF8\uB3C4 \uC5C6\uACE0 \uC758\uBBF8\uB3C4 \uC5C6\uB294 \uBB38\uC81C\uAC00 \uB41C \uAC83 \uAC19\uB2E4. (\uD5C8\uBB34\uD568\uC744 \uB290\uB080 \uC0AC\uB78C\uB3C4 \uC788\uB354\uB77C \u3160\u3160)\\n\\n## FaceScore (Web)\\n\\n> AI (\uC544\uB2D8)\\n\\n### \uACB0\uACFC\\n\\n920\uC810 (5 Solves)\\n\\n### \uCD9C\uC81C \uC758\uB3C4\\n\\nLog4j\uC640 react2shell\uB294 \uBBF8\uB9AC \uB9C9\uC744 \uC218 \uC5C6\uC5C8\uB2E4\uB294 \uACF5\uD1B5\uC810\uC774 \uC788\uB2E4. \uBAA8\uB4C8\uD654\uC640 \uC758\uC874\uC131\uC758 \uC2DC\uB300\uC5D0\uC11C \uAC1C\uBC1C\uC790\uAC00 \uC544\uBB34\uB9AC \uC798 \uB9C9\uC544\uB3C4 \uCDE8\uC57D\uC810\uC774 \uBC1C\uC0DD\uD560 \uC218 \uC788\uB2E4\uB294 \uAC83\uC744 \uBCF4\uC5EC\uC8FC\uB294 \uC0AC\uB840\uC774\uAE30\uB3C4 \uD558\uB2E4. \uADF8\uB798\uC11C CERT\uAC00 \uC911\uC694\uD55C \uAC83 \uAC19\uB2E4. \uC9C0\uC778\uB4E4 \uC911 \uC5F0\uB9D0\uC5D0 \uB54C\uC544\uB2CC \uC57C\uADFC, \uC8FC\uB9D0 \uADFC\uBB34\uB97C \uD558\uBA70 \uB208\uBB3C \uD758\uB9AC\uB358 \uBAA8\uC2B5\uC774 \uC0C8\uB85D\uC0C8\uB85D\uD558\uB2E4.\\n\\n\uC11C\uB450\uC5D0\uC11C \uB9D0\uD588\uB4EF react2shell\uC758 \uAC15\uB825\uD568\uC744 \uCCB4\uAC10\uC2DC\uCF1C\uC8FC\uAE30 \uC704\uD55C \uC774 \uBB38\uC81C\uC758 \uCEE8\uC149\uC740 \uCDE8\uC57D\uD558\uC9C0 \uC54A\uC740 \uC11C\uBE44\uC2A4\uC640 \uCDE8\uC57D \uBC84\uC804(15.1.0)\uC758 Next.js \uD504\uB808\uC784\uC6CC\uD06C\uC600\uB2E4.\\n\\n### \uC758\uB3C4\uD55C \uD480\uC774 \uBC29\uD5A5\\n\\n1. Burpsuite\uB97C \uD1B5\uD574 \uD504\uB85D\uC2DC\uB97C \uC7A1\uACE0 \uD574\uB2F9 \uC11C\uBE44\uC2A4\uB97C \uC774\uC6A9\uD55C\uB2E4. (\uC0AC\uC9C4\uC744 \uC5C5\uB85C\uB4DC \uD558\uC5EC Server Action\uC774 \uC0AC\uC6A9\uB418\uB294 \uC5BC\uAD74 \uD3C9\uAC00\uB97C \uBC1B\uB294\uB2E4.)\\n2. `POST /` \uC6F9 \uC694\uCCAD\uC744 \uBCF4\uBA74 Next-Action \uD5E4\uB354\uB97C \uD1B5\uD574 Next.js\uC5D0\uC11C Server Action\uC774 \uC0AC\uC6A9\uB418\uACE0 \uC788\uB294 \uAC83\uC744 \uD655\uC778\uD560 \uC218 \uC788\uB2E4. \uB610\uD55C `$K1` \uD45C\uD604\uC2DD\uC744 \uD1B5\uD574 Flight \uD504\uB85C\uD1A0\uCF5C\uC744 \uC774\uC6A9\uD55C \uC9C1\uB82C\uD654\uAC00 \uC218\uD589\uB418\uACE0 \uC788\uC74C\uC744 \uBCFC \uC218 \uC788\uB2E4. \uC774\uB97C \uD1B5\uD574 \uD604\uC7AC \uD574\uB2F9 \uC11C\uBE44\uC2A4\uC5D0\uC11C react2shell \uCDE8\uC57D\uC810\uC774 \uBC1C\uC0DD\uD560 \uC218 \uC788\uB2E4\uACE0 \uCD94\uCE21\uD560 \uC218 \uC788\uB2E4.\\n    ```\\n    POST / HTTP/1.1\\n    Host: kknock.org:10010\\n    Content-Length: 126239\\n    User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36\\n    Next-Action: 608e49ccb4089e3d50cfca3a2ab71eea561c1f5c79\\n    Accept-Language: ko-KR,ko;q=0.9\\n    Accept: text/x-component\\n    Content-Type: multipart/form-data; boundary=----WebKitFormBoundaryopzYToGMpm6ZnyAh\\n    Next-Router-State-Tree: %5B%22%22%2C%7B%22children%22%3A%5B%22__PAGE__%22%2C%7B%7D%2C%22%2F%22%2C%22refresh%22%5D%7D%2Cnull%2Cnull%2Ctrue%5D\\n    Origin: http://kknock.org:10010\\n    Referer: http://kknock.org:10010/\\n    Accept-Encoding: gzip, deflate, br\\n    Connection: keep-alive\\n\\n    ------WebKitFormBoundaryopzYToGMpm6ZnyAh\\n    Content-Disposition: form-data; name=\\"1_score\\"\\n\\n    100\\n    ------WebKitFormBoundaryopzYToGMpm6ZnyAh\\n    Content-Disposition: form-data; name=\\"1_comment\\"\\n\\n    \uC624\uB298 \uBBF8\uBAA8\u2026 \uBC18\uCE59\\n    ------WebKitFormBoundaryopzYToGMpm6ZnyAh\\n    Content-Disposition: form-data; name=\\"1_image\\"; filename=\\"share.webp\\"\\n    Content-Type: image/webp\\n\\n    ... \uC0AC\uC9C4 \uB370\uC774\uD130 ...\\n    ------WebKitFormBoundaryopzYToGMpm6ZnyAh\\n    Content-Disposition: form-data; name=\\"0\\"\\n\\n    [{\\"ok\\":false,\\"message\\":\\"\\"},\\"$K1\\"]\\n    ------WebKitFormBoundaryopzYToGMpm6ZnyAh--\\n\\n    ```\\n3. \uBB3C\uB860 react2shell\uC758 \uC0AC\uC804 \uC9C0\uC2DD\uC774 \uC5C6\uC5B4 \uC694\uCCAD\uC5D0\uC11C \uC5BB\uC744 \uC218 \uC788\uB294 \uC815\uBCF4\uB97C \uC9C0\uB098\uCE60 \uC218 \uC788\uB2E4. \uD558\uC9C0\uB9CC \uC751\uB2F5\uC744 \uD655\uC778\uD574\uBCF4\uBA74 Next.js \uD504\uB808\uC784\uC6CC\uD06C\uB97C \uC0AC\uC6A9\uD55C\uB2E4\uB294 \uAC83\uC744 \uD655\uC2E4\uD558\uAC8C \uC54C \uC218 \uC788\uB294\uB370 \uD604\uC7AC `next.js \uCDE8\uC57D\uC810`\uC744 \uAD6C\uAE00\uC5D0 \uCE58\uBA74 \uB9CE\uC740 \uAE00\uC774 react2shell \uCDE8\uC57D\uC810\uC744 \uB2E4\uB8E8\uACE0 \uC788\uB2E4. \uC5EC\uB7EC [react2shell \uCDE8\uC57D\uC810 \uC5F0\uAD6C \uAE00](https://zi-en.io/resources/tech/118)\uC744 \uC77D\uC5B4\uC11C \uD574\uB2F9 \uCDE8\uC57D\uC810\uC744 \uC774\uD574\uD558\uBA74 \uB41C\uB2E4.\\n    ```\\n    HTTP/1.1 200 OK\\n    Vary: RSC, Next-Router-State-Tree, Next-Router-Prefetch, Next-Router-Segment-Prefetch, Accept-Encoding\\n    Cache-Control: no-cache, no-store, max-age=0, must-revalidate\\n    x-action-revalidated: [[],0,0]\\n    x-nextjs-cache: HIT\\n    x-nextjs-prerender: 1\\n    X-Powered-By: Next.js\\n    Content-Type: text/x-component\\n    Date: Wed, 24 Dec 2025 20:40:32 GMT\\n    Connection: keep-alive\\n    Keep-Alive: timeout=5\\n    Content-Length: 79\\n\\n    0:{\\"a\\":\\"$@1\\",\\"f\\":\\"\\",\\"b\\":\\"KsN3asGDaFsh3Eaiu0hZJ\\"}\\n    1:{\\"ok\\":true,\\"id\\":\\"S8dBe100\\"}\\n    ```\\n4. \uBC84\uC804 \uC815\uBCF4 \uB178\uCD9C\uC774 \uBC1C\uC0DD\uD55C \uAC83\uC740 \uC544\uB2C8\uAE30 \uB54C\uBB38\uC5D0 \uC544\uC9C1 \uD655\uC2E4\uD788 \uCDE8\uC57D\uC810\uC774 \uC874\uC7AC\uD558\uB294\uC9C0\uB294 \uC54C \uC218 \uC5C6\uB2E4. \uCDE8\uC57D \uBC84\uC804\uC744 \uC0AC\uC6A9\uD558\uB294\uC9C0 \uC774\uB97C \uD1B5\uD574 \uCDE8\uC57D\uC810\uC774 \uBC1C\uC0DD\uD560 \uD655\uB960\uC774 \uC788\uB294\uC9C0\uB97C \uAC04\uB2E8\uD788 \uD655\uC778\uD558\uAE30 \uC704\uD574 React2Shell Scanner\uB97C \uD65C\uC6A9\uD560 \uC218 \uC788\uB2E4. ZIEN\uC5D0\uC11C \uAC1C\uBC1C\uD55C [React2Shell \uC2A4\uCE90\uB108](https://react2shell-scanner.zi-en.io/)\uB97C \uD1B5\uD574 \uC2A4\uCE94\uD574\uBCF4\uBA74 \uCDE8\uC57D\uC810\uC774 \uC874\uC7AC\uD558\uB294 \uAC83\uC744 \uD655\uC778 \uD560 \uC218 \uC788\uB2E4.\\n    ![react2shell_scan_result_using_zien_r2s_scanner](kctf-2025_review/react2shell_scanner_result.png)\\n5. \uC9F1\uC9F1 \uC9C0\uC5D4 \uC2A4\uCE90\uB108\uB294 \uC2EC\uC9C0\uC5B4 HTTP \uC694\uCCAD / \uC751\uB2F5\uB3C4 \uBCF4\uC5EC\uC8FC\uB294\uB370 \uC720\uD6A8\uD558\uC9C0 \uC54A\uC740 Action ID\uC5D0 \uB300\uD574\uC11C `Server action not found.` \uC751\uB2F5\uC774 \uC544\uB2CC \uC11C\uBC84 \uC5D0\uB7EC\uAC00 \uC751\uB2F5\uB418\uB294\uAC78\uB85C \uD604\uC7AC \uC0AC\uC6A9\uC911\uC778 Next.js\uBC84\uC804\uC774 React2Shell\uC5D0 \uCDE8\uC57D\uD55C \uAC83\uC744 \uD655\uC778\uD560 \uC218 \uC788\uB2E4. (\uBD80\uC5F0\uC124\uBA85\uC744 \uC9E4\uB9C9\uD558\uAC8C \uD558\uC790\uBA74 \uD574\uB2F9 \uC11C\uBC84\uC5D0\uB7EC\uB294 `{}`\uC5D0 \uC5C6\uB294 \uC18D\uC131 `\\"zi\\"`\uC5D0 \uB300\uD574 \uC811\uADFC\uD558\uC5EC `undefined`\uC774 \uB41C \uD6C4 `undefined`\uC758 \uC18D\uC131\uC744 \uC77D\uC73C\uB824\uB2E4 \uBC1C\uC0DD\uD55C \uAC83\uC774\uB2E4.)\\n    ![react2shell_scan_result_using_zien_r2s_scanner](kctf-2025_review/react2shell_scanner_result_detail.png)\\n6. \uC774\uC81C \uC774 \uCDE8\uC57D\uC810\uC744 \uC774\uC6A9\uD560 \uCC28\uB840\uB2E4, CVE-2025-55182 PoC\uB97C \uAC80\uC0C9\uD574\uBCF4\uBA74 [\uC218 \uB9CE\uC740 \uD398\uC774\uB85C\uB4DC](https://github.com/Malayke/Next.js-RSC-RCE-Scanner-CVE-2025-66478?tab=readme-ov-file#payload-that-can-see-command-execution-result-in-response-body-most-useful)\uAC00 \uB098\uC624\uB294\uB370 \uADF8 \uC911 \uD558\uB098\uB97C \uAC00\uC838\uB2E4 \uC4F0\uBA74 \uB41C\uB2E4. \uC0AC\uC9C4 \uB0B4 \uAC04\uB2E8 \uC124\uBA85\uC5D0\uC11C react2shell\uC758 \uCDE8\uC57D\uC810 \uCCB4\uC778 3\uAC1C \uC911 \uAC00\uC7A5 \uC911\uC694\uD55C then \uBD80\uBD84\uC744 \uACFC\uAC10\uD788 \uC0DD\uB7B5\uD588\uB294\uB370 \uC0AC\uC2E4 \uC0DD\uB7B5\uD558\uBA74 \uC548\uB41C\uB2E4. \uD558\uC9C0\uB9CC \uC774\uAC83\uB9CC \uB2E4\uB904\uB3C4 \uD604\uC7AC \uC774 \uAE00\uC758 \uBD84\uB7C9\uC815\uB3C4 \uB420 \uAC83 \uAC19\uC544\uC11C [\uC9C0\uC5D4](https://zi-en.io/resources/tech/118)\uC774\uB098 [\uC5D4\uD0A4 \uC5F0\uAD6C \uAE00](https://www.enki.co.kr/media-center/blog/complete-analysis-of-the-react2shell-cve-2025-55182-vulnerability)\uC5D0\uC11C \uC798 \uB2E4\uB8E8\uACE0 \uC788\uC73C\uB2C8 \uCC38\uACE0\uD558\uBA74 \uC88B\uC744 \uAC83 \uAC19\uB2E4.\\n    ![react2shell_exploit_result_and_detail](kctf-2025_review/exploit_detail.png)\\n\\n\\n### \uC5EC\uB2F4\\n\\nAI\uB77C\uB294 \uD0A4\uC6CC\uB4DC\uAC00 \uD56B\uD558\uB2C8\uAE4C \uAC00\uC838\uB2E4 \uC4F4\uAC74\uB370 \uC5C5\uB85C\uB4DC \uB41C \uC0AC\uC9C4\uB4E4\uC744 \uBCF4\uB2C8 LLM\uC744 \uC18D\uC774\uB294 \uC0AC\uC9C4\uC744 \uC62C\uB9B0\uAC8C \uB9CE\uC774 \uBC1C\uACAC\uB418\uC5C8\uB2E4. \uC18D\uC774\uB824\uACE0 \uD55C \uAC74 \uC544\uB2CC\uB370 \uBBF8\uC548\uD558\uAC8C \uB418\uC5C8\uB2E4 \uD5C8\uD5C8,,, \uC810\uC218\uB294 \uC11C\uBC84\uC5D0\uC11C 80~100 \uB79C\uB364\uC73C\uB85C \uC8FC\uB3C4\uB85D \uD588\uACE0 \uC544\uC774\uB3CC \uD32C\uC758 \uC2DC\uC120\uC73C\uB85C \uC544\uC774\uB3CC \uC0AC\uC9C4\uC774 \uB9CE\uC774 \uC62C\uB77C\uC62C \uC904 \uC54C\uC558\uB294\uB370 \uC758\uBB38\uC758 \uB450\uCAC0\uCFE0 \uAD70\uB2E8\uC744 \uB9DE\uC774\uD558\uAC8C \uB418\uC5C8\uB2E4. \uC798 \uB9CC\uB4E0 \uC11C\uBE44\uC2A4 \uAC19\uC544\uC11C \uB0B4\uB144 \uBB38\uC81C\uC5D0\uB3C4 \uAC00\uC838\uB2E4 \uC4F8 \uAC83 \uAC19\uC740\uB370 \uADF8 \uB550 \uC9C4\uC9DC LLM\uC744 \uB3C4\uC785\uD558\uBA74 \uB354 \uC7AC\uBC0C\uC744\uC9C0\uB3C4 \uBAA8\uB974\uACA0\uB2E4 \u314E\u314E\\n\\n```bash\\n\u276F find data/shares -maxdepth 1 -type f | wc -l # \uCD1D \uC81C\uCD9C\uB41C \uC0AC\uC9C4 \uC218\\n238\\n```"},{"id":"/memo_docusaurus","metadata":{"permalink":"/blog/memo_docusaurus","source":"@site/blog/memo_docusaurus.md","title":"Docusaurus \uC0BD\uC9C8 \uAE30\uB85D","description":"\uD604\uC7AC \uC774 \uC0AC\uC774\uD2B8\uC758 \uC5D4\uC9C4\uC778 Docusaurus\uB97C \uC0AC\uC6A9\uD558\uBA74\uC11C \uD55C \uB9CE\uC740 \uC0BD\uC9C8\uC744 \uAE30\uB85D\uD560 \uC608\uC815\uC774\uB2E4.","date":"2022-04-18T00:00:00.000Z","tags":[{"inline":true,"label":"memo","permalink":"/blog/tags/memo"},{"inline":true,"label":"docs","permalink":"/blog/tags/docs"},{"inline":true,"label":"docusaurus","permalink":"/blog/tags/docusaurus"},{"inline":true,"label":"api","permalink":"/blog/tags/api"}],"readingTime":0.24,"hasTruncateMarker":true,"authors":[{"name":"SYRU","title":"security researcher","url":"https://github.com/l0vey0u","imageURL":"https://avatars.githubusercontent.com/u/30224688","key":"syru","page":null}],"frontMatter":{"title":"Docusaurus \uC0BD\uC9C8 \uAE30\uB85D","authors":"syru","tags":["memo","docs","docusaurus","api"],"date":"2022-04-18T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"2025 \uACBD\uAE30\uB300\uD559\uAD50 \uD574\uD0B9\uBC29\uC5B4\uB300\uD68C \uCD9C\uC81C \uD6C4\uAE30","permalink":"/blog/kctf-2025_review"},"nextItem":{"title":"\uC6F9 \uB2E4\uC2DC \uC0B4\uD3B4\uBCF4\uAE30 (1)","permalink":"/blog/re-zero-web-pt1"}},"content":"\uD604\uC7AC \uC774 \uC0AC\uC774\uD2B8\uC758 \uC5D4\uC9C4\uC778 Docusaurus\uB97C \uC0AC\uC6A9\uD558\uBA74\uC11C \uD55C \uB9CE\uC740 \uC0BD\uC9C8\uC744 \uAE30\uB85D\uD560 \uC608\uC815\uC774\uB2E4. \\n{/* truncate */}\\n\\n### Blog \uAE00 \uC804\uCCB4\uB97C \uBCF4\uC5EC\uC904 \uD544\uC694\uB294 \uC5C6\uB294\uB370...!\\n```html\\n\x3c!--truncate--\x3e\\n```\\n\uD574\uB2F9 \uD0DC\uADF8\uB97C \uC0BD\uC785\uD558\uBA74 \uBE14\uB85C\uADF8 \uAE00 \uBAA9\uB85D\uACFC \uADF8 \uB0B4\uC6A9\uC774 \uCD9C\uB825\uB420 \uB54C \uC774 \uD0DC\uADF8 \uC704\uAE4C\uC9C0\uB97C \uBBF8\uB9AC\uBCF4\uAE30 \uD615\uD0DC\uB85C \uC81C\uACF5\uD558\uBA70 \uB098\uBA38\uC9C0 \uB0B4\uC6A9\uC740 \uAC00\uB824\uC9C4\uB2E4.\\n\\n### 26. 09. 07 \uBCC0\uACBD\uC0AC\uD56D\\n`{/* truncate */}`\uB85C \uBC14\uB00C\uC5C8\uB2E4."},{"id":"/re-zero-web-pt1","metadata":{"permalink":"/blog/re-zero-web-pt1","source":"@site/blog/re-zero-web-pt1.md","title":"\uC6F9 \uB2E4\uC2DC \uC0B4\uD3B4\uBCF4\uAE30 (1)","description":"\uADF8 \uB3D9\uC548 \uC6F9 \uC11C\uBE44\uC2A4 \uBCF4\uC548 \uCDE8\uC57D\uC810\uC744 \uACF5\uBD80\uD558\uACE0 \uD65C\uC6A9\uD560 \uB54C \uB9C8\uB2E4 \uB0B4\uAC00 \uC6F9\uC5D0 \uB300\uD574 \uAD81\uAE08\uD558\uC9C0\uB9CC \uBC14\uBE60\uC11C \uB118\uC5B4\uAC14\uB358 \uBD80\uBD84\uC774 \uB9CE\uC558\uB2E4.","date":"2022-04-07T18:00:00.000Z","tags":[{"inline":true,"label":"research","permalink":"/blog/tags/research"},{"inline":true,"label":"web","permalink":"/blog/tags/web"}],"readingTime":1.41,"hasTruncateMarker":true,"authors":[{"name":"SYRU","title":"security researcher","url":"https://github.com/l0vey0u","imageURL":"https://avatars.githubusercontent.com/u/30224688","key":"syru","page":null}],"frontMatter":{"title":"\uC6F9 \uB2E4\uC2DC \uC0B4\uD3B4\uBCF4\uAE30 (1)","authors":"syru","tags":["research","web"],"date":"2022-04-07T18:00:00.000Z"},"unlisted":false,"prevItem":{"title":"Docusaurus \uC0BD\uC9C8 \uAE30\uB85D","permalink":"/blog/memo_docusaurus"},"nextItem":{"title":"\uC7AC\uBC0C\uB294 HTTP Request Smuggling \uC774\uC57C\uAE30 (2)","permalink":"/blog/funny-smuggling-story-pt2"}},"content":"\uADF8 \uB3D9\uC548 \uC6F9 \uC11C\uBE44\uC2A4 \uBCF4\uC548 \uCDE8\uC57D\uC810\uC744 \uACF5\uBD80\uD558\uACE0 \uD65C\uC6A9\uD560 \uB54C \uB9C8\uB2E4 \uB0B4\uAC00 \uC6F9\uC5D0 \uB300\uD574 \uAD81\uAE08\uD558\uC9C0\uB9CC \uBC14\uBE60\uC11C \uB118\uC5B4\uAC14\uB358 \uBD80\uBD84\uC774 \uB9CE\uC558\uB2E4.\\n\uC774\uC81C \uC880 \uC5EC\uC720\uB97C \uCC3E\uC544\uC11C \uAD81\uAE08\uC99D\uB3C4 \uD574\uC18C\uD558\uBA74\uC11C \uC6F9\uC5D0 \uB300\uD574 \uC870\uAE08 \uB354 \uC774\uD574\uD558\uB294 \uC2DC\uAC04\uC744 \uAC00\uC838\uBCFC\uAE4C \uD55C\uB2E4.\\n\uB4DC\uB9BC\uD575\uC758 \uC6F9 \uC11C\uBE44\uC2A4 \uBCF4\uC548 \uCEE4\uB9AC\uD058\uB7FC\uC744 \uD559\uC2B5\uD558\uBA74\uC11C \uB2E8\uC5B4\uB098 \uBB38\uC7A5\uC5D0 \uC0DD\uAE34 \uAD81\uAE08\uC810\uC744 \uC801\uC5B4\uB450\uACE0 \uC774\uC5D0 \uB300\uD574 \uC54C\uC544\uBCF4\uACE0 \uC815\uB9AC\uD574\uBCF4\uB294 \uBC29\uC2DD\uC73C\uB85C \uD560 \uC0DD\uAC01\uC774\uB2E4.\\n\\n## URL\uACFC URI\\n\\n URL\uACFC URI\uB294 \uAC01\uAC01 [RFC1738](https://www.rfc-editor.org/rfc/rfc1738) \uC640 [RFC3986](https://www.rfc-editor.org/rfc/rfc3986)\uC5D0 \uC815\uC758\uB418\uC5B4\uC788\uB2E4.\\n{/* truncate */}\\n\uC5B4\uCC0C\uBCF4\uBA74 \uAC19\uC740 \uC758\uBBF8\uC758 \uB2E8\uC5B4\uAC00 3\uAC1C\uB098 (+URN, \uC2E4\uC81C\uB860 \uBCC4\uB85C \uC548\uC4F0\uB2C8 \uB0B4\uC6A9\uC5D4 \uD3EC\uD568\uD558\uC9C0 \uC54A\uACA0\uB2E4) \uC788\uACE0 \uADF8\uAC83\uC774 \uACC4\uC18D \uC720\uC9C0\uB418\uC5C8\uB2E4\uB294 \uAC83\uC740 \uAC01\uAC01\uC774 \uC0C1\uC9D5\uC801\uC778 \uC758\uBBF8\uB97C \uAC00\uC9C0\uACE0 \uC788\uB2E4\uACE0 \uBCFC \uC218 \uC788\uB2E4.\\n\uB2E4\uD589\uD788\uB3C4 [RFC3986 1.1.3 \uD56D\uBAA9](https://www.rfc-editor.org/rfc/rfc3986#section-1.1.3)\uC5D0\uC11C \uC774 \uB0B4\uC6A9\uC774 \uC774\uBBF8 \uC18C\uAC1C\uB418\uC5B4\uC788\uB2E4.\\nURI\uAC00 \uB354 \uD3EC\uAD04\uC801\uC778 Identifier\uB85C\uC11C\uC758 \uC758\uBBF8\uB97C \uAC00\uC9C0\uACE0 URL\uACFC URN\uC73C\uB85C \uBD84\uB958\uB420 \uC218 \uC788\uB2E4. URN\uC740 constant\uD55C name\uC73C\uB85C\uC11C, URL\uC740 locator\uB85C\uC11C\uC758 \uC758\uBBF8\uB97C \uAC00\uC9C4\uB2E4.\\n\\n URI\uB294 \uD3EC\uAD04\uC801\uC73C\uB85C \uC4F0\uAE30 \uC88B\uC740 \uB2E8\uC5B4\uB77C\uACE0 \uD560 \uB54C URL\uC774\uB77C\uACE0 \uD558\uBA74 \uC548\uB418\uB294 URI\uB294 \uBB34\uC5C7\uC77C\uAE4C? URL\uC744 \uB354 \uD30C\uACE0\uB4E4\uC5B4\uAC00\uBCF4\uC790\\nURL\uC740 \uD2B9\uC815 \uC790\uC6D0\uC758 \uC704\uCE58\uC640 \uC811\uADFC\uC5D0 \uB300\uD55C \uC815\uBCF4\uB97C \uB2F4\uC740 \uBB38\uC790\uC5F4\uC774\uB2E4. \uD2B9\uC815 \uC790\uC6D0\uC758 \uC704\uCE58\uB97C \uAC00\uB9AC\uD0A4\uC9C0 \uBABB\uD558\uBA74 URL\uC774 \uC544\uB2C8\uB2E4. \uC608\uB97C \uB4E4\uC5B4 \uD604\uC7AC\uC2DC\uAC04\uC744 \uCD9C\uB825\uD558\uB294 api \uC8FC\uC18C\uAC00 \uC788\uB2E4\uACE0 \uD558\uC790 \uD574\uB2F9 URI\uB294 URL\uB3C4 URN\uB3C4 \uB420 \uC218 \uC5C6\uB2E4. \uD2B9\uC815 \uC790\uC6D0\uACFC \uAD00\uB828\uC774 \uC5C6\uAE30 \uB54C\uBB38\uC774\uB2E4. \uC774\uC5D0 \uB530\uB978 \uB17C\uC758\uB294 \uB354 \uB420 \uC218 \uC788\uC744 \uAC83 \uAC19\uB2E4. \uC2DC\uAC04\uC774\uB780 \uAC83\uB3C4 \uC790\uC6D0\uC73C\uB85C \uD574\uC11D\uB420 \uC218 \uC788\uB2E4\uACE0 \uBCF8\uB2E4. \uD558\uC9C0\uB9CC \uC77C\uBC18\uC801\uC778 \uC0C1\uD669\uC5D0\uC11C\uB294 \uADF8\uB0E5 URI\uB77C\uACE0 \uD558\uBA74 \uB41C\uB2E4.\\n\\nURN\uC740 \uBB34\uC5C7\uC778\uC9C0 \uAD81\uAE08\uD574\uC11C chatgpt\uB97C \uD65C\uC6A9\uD574\uC11C \uC0B4\uD3B4\uBCF4\uC558\uB2E4. URN\uC740 urn:ietf:rfc:1738\uACFC \uAC19\uC774 \uC778\uD130\uB137 \uC0C1 \uBB38\uC11C\uB098 urn:isbn:~ \uACFC \uAC19\uC740 isbn\uBC88\uD638 \uAC19\uC740 \uC870\uAE08\uC740 \uB354 \uD3EC\uAD04\uC801\uC73C\uB85C \uC790\uC6D0\uC758 \uC774\uB984\uC5D0 \uB300\uD55C \uC815\uBCF4\uB85C \uC4F0\uB294 \uBB38\uC790\uC5F4\uC774\uB2E4. \uD558\uC9C0\uB9CC \uC77C\uBC18\uC801\uC73C\uB860 \uC798 \uC548 \uC4F0\uB2C8 \uC54C\uACE0\uB9CC \uC788\uC73C\uBA74 \uB420 \uAC83 \uAC19\uB2E4.\\n\\n---\\n\\n### Reference\\n- [RFC1738](https://www.rfc-editor.org/rfc/rfc1738)\\n- [RFC3986](https://www.rfc-editor.org/rfc/rfc3986)"},{"id":"/funny-smuggling-story-pt2","metadata":{"permalink":"/blog/funny-smuggling-story-pt2","source":"@site/blog/funny-smuggling-story-pt2.md","title":"\uC7AC\uBC0C\uB294 HTTP Request Smuggling \uC774\uC57C\uAE30 (2)","description":"\uC548\uB155\uD558\uC138\uC694 : ) \uC2DC\uB8E8\uC785\uB2C8\uB2E4.","date":"2022-03-06T18:00:00.000Z","tags":[{"inline":true,"label":"research","permalink":"/blog/tags/research"},{"inline":true,"label":"http","permalink":"/blog/tags/http"},{"inline":true,"label":"http smuggling","permalink":"/blog/tags/http-smuggling"}],"readingTime":3.66,"hasTruncateMarker":true,"authors":[{"name":"SYRU","title":"security researcher","url":"https://github.com/l0vey0u","imageURL":"https://avatars.githubusercontent.com/u/30224688","key":"syru","page":null}],"frontMatter":{"title":"\uC7AC\uBC0C\uB294 HTTP Request Smuggling \uC774\uC57C\uAE30 (2)","authors":"syru","tags":["research","http","http smuggling"],"date":"2022-03-06T18:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\uC6F9 \uB2E4\uC2DC \uC0B4\uD3B4\uBCF4\uAE30 (1)","permalink":"/blog/re-zero-web-pt1"},"nextItem":{"title":"\uC0AC\uC18C\uD55C \uD301 \uB4E4 \uC815\uB9AC","permalink":"/blog/memo_tips"}},"content":"\uC548\uB155\uD558\uC138\uC694 : ) \uC2DC\uB8E8\uC785\uB2C8\uB2E4.\\n\\n[\uC800\uBC88 \uAE00](/blog/funny-smuggling-story-pt1/)\uC5D0\uC11C\uB294 HTTP Request Smuggling\uC774 \uBB34\uC5C7\uC778\uC9C0\uC5D0 \uB300\uD574\uC11C \uC54C\uB824\uB4DC\uB838\uB294\uB370\uC694.\\n\\n\uC624\uB298\uC740 \uC6B0\uB9AC \uC8FC\uBCC0\uC5D0 \uC0AC\uC6A9\uB418\uB294 \uD504\uB85C\uADF8\uB7A8\uC5D0\uC11C \uC774 \uAE30\uBC95\uC73C\uB85C \uACF5\uACA9\uC774 \uAC00\uB2A5\uD55C \uCDE8\uC57D\uC810\uC774 \uBC1C\uC0DD\uD55C \uC0AC\uB840\uB97C \uC54C\uC544\uBCF4\uACA0\uC2B5\uB2C8\uB2E4.\\n\\n\\n{/* truncate */}\\n\\n## \uC7A0\uAE50, HTTP Request Smuggling\uC774 \uBB50\uC600\uC9C0?\\n\\n\uC0AC\uB840 \uC5F0\uAD6C\uC5D0 \uC55E\uC11C \uBCF5\uC2B5\uC744 \uD574\uBD05\uC2DC\uB2E4.\\n\\n\uC774 \uACF5\uACA9 \uAE30\uBC95\uC740 HTTP \uC694\uCCAD\uC774 \uCC98\uB9AC\uB420 \uB54C \uC774\uC804 \uC694\uCCAD\uC774 \uB2E4\uC74C \uC694\uCCAD\uC5D0 \uD3EC\uD568\uB418\uC5B4 \uD574\uB2F9 \uC694\uCCAD\uC758 \uCC98\uB9AC\uACB0\uACFC\uB97C \uBC14\uAFB8\uB294 \uAC83\uC774\uC5C8\uC2B5\uB2C8\uB2E4.\\n\\n\uC6F9 \uC11C\uBE44\uC2A4 \uC778\uD504\uB77C\uB97C \uAD6C\uC131\uD560 \uB54C \uD2B8\uB798\uD53D \uBD84\uC0B0, \uCE90\uC2F1 \uB4F1\uC744 \uC704\uD574 \uD504\uB85D\uC2DC\uB97C \uBC30\uCE58\uD558\uAC8C \uB418\uB294\uB370 \uC774 \uD504\uB85D\uC2DC\uC640 \uC6F9 \uC11C\uBC84\uAC00 \uC11C\uB85C HTTP \uC694\uCCAD\uC758 Body \uAE38\uC774\uC5D0 \uB300\uD55C \uD574\uC11D\uC744 \uB2E4\uB974\uAC8C \uD558\uBA74\uC11C \uC8FC\uB85C \uBC1C\uC0DD\uD569\uB2C8\uB2E4. \\n\\nBody\uC758 \uAE38\uC774\uB294 Content-Length \uD5E4\uB354\uB098 Transfer-Encoding \uD5E4\uB354\uB97C \uD1B5\uD574 \uACB0\uC815\uB418\uBA70 \uC544\uB798\uC758 \uADDC\uCE59\uC774 \uC874\uC7AC\uD569\uB2C8\uB2E4.\\n\\n1. Content-Length \uD5E4\uB354\uAC00 2\uAC1C \uC774\uC0C1 \uC874\uC7AC\uD558\uBA74 400 Bad Request\uB85C \uCC98\uB9AC\uD55C\uB2E4.\\n2. Content-Length \uD5E4\uB354\uC640 Transfer-Encoding \uD5E4\uB354\uAC00 \uB3D9\uC2DC\uC5D0 \uC874\uC7AC\uD558\uBA74 Transfer-Encoding\uC744 \uB530\uB978\uB2E4.\\n\\n\uADDC\uCE59\uC744 \uC77D\uC5B4\uBCF4\uBA74 \uD45C\uC900\uC5D0 \uB530\uB974\uAE30\uB9CC \uD574\uB3C4 Smuggling\uC774 \uBC29\uC9C0\uB420 \uAC83 \uAC19\uC2B5\uB2C8\uB2E4.\\n\\n\uD558\uC9C0\uB9CC \uACF5\uACA9\uC790\uB4E4\uC740 \uC5F0\uAD6C \uB05D\uC5D0 \uC544\uB798 \uBC29\uBC95\uC744 \uC0AC\uC6A9\uD558\uC5EC \uC774\uB97C \uC6B0\uD68C \uD558\uC600\uC2B5\uB2C8\uB2E4.\\n\\n1. \uD2B9\uC218\uD55C \uC785\uB825\uAC12\uC744 \uD1B5\uD574 \uD2B9\uC815 \uD30C\uC11C\uC758 \uD30C\uC2F1 \uACB0\uACFC\uB97C \uB2E4\uB974\uAC8C \uB098\uC624\uB3C4\uB85D \uC720\uB3C4\uD558\uAE30\\n2. \uD30C\uC11C\uC758 \uC798\uBABB\uB41C \uCC98\uB9AC\uB85C\uC9C1\uC744 \uC774\uC6A9\uD558\uAE30\\n\\n\\n\\n## \uACF5\uACA9 \uC0AC\uB840\\n\\n\uD3B8\uC758\uB97C \uC704\uD574 Content-Length\uB97C CL, Transfer-Encoding\uC744 TE\uB77C\uACE0 \uBD80\uB974\uACA0\uC2B5\uB2C8\uB2E4. \\n\\n### CL-CL + \uD2B9\uC815 \uD30C\uC11C\uC758 \uD30C\uC2F1 \uACB0\uACFC\uB97C \uB2E4\uB974\uAC8C \uB098\uC624\uB3C4\uB85D \uC720\uB3C4\uD558\uAE30\\n\\nHAProxy\uB294 \uACE0\uAC00\uC6A9\uC131(HA)\uC744 \uC704\uD574 \uC8FC\uB85C \uC0AC\uC6A9\uB418\uB294 \uD504\uB85D\uC2DC \uC785\uB2C8\uB2E4.\\n\\n\uC791\uB144 9\uC6D4\uC5D0 \uC774 \uD504\uB85D\uC2DC\uC5D0\uC11C CL-CL \uC720\uD615\uC758 HTTP Request Smuggling\uC774 \uBC1C\uACAC\uB418\uC5C8\uC2B5\uB2C8\uB2E4.\\n\\n\uD574\uB2F9 \uC720\uD615\uC774 \uB3D9\uC791\uD558\uB824\uBA74 \uB450 \uD30C\uC2F1 \uB2E8\uACC4\uC5D0\uC11C 400 bad request \uCC98\uB9AC\uB97C \uB9C9\uC544\uC57C\uD569\uB2C8\uB2E4.\\n\\n\uC989 \uCC98\uB9AC\uD558\uB294 \uC21C\uAC04\uC5D0\uB294 CL \uD5E4\uB354\uB294 \uD558\uB098\uB9CC \uC788\uB294 \uAC83\uC73C\uB85C \uBCF4\uC5EC\uC57C \uD569\uB2C8\uB2E4.\\n\\n\uD574\uB2F9 \uCDE8\uC57D \uBC84\uC83C\uC5D0\uC11C HAProxy\uB294 \uD30C\uC2F1\uB2E8\uACC4\uC5D0\uC11C CL\uC774 \uD55C\uBC88 \uC815\uC0C1\uC801\uC73C\uB85C \uCC98\uB9AC\uB418\uBA74 \uB098\uBA38\uC9C0 \uD5E4\uB354\uB294 \uBB34\uC2DC\uD558\uB3C4\uB85D \uD504\uB85C\uADF8\uB798\uBC0D \uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n\uADF8\uB807\uAE30\uC5D0 HAProxy\uAC00 \uC6F9 \uC11C\uBC84\uB85C \uC804\uB2EC\uD558\uB294 HTTP \uC694\uCCAD\uC5D0\uB294 CL \uD5E4\uB354\uAC00 \uD558\uB098\uB9CC \uC874\uC7AC\uD558\uAC8C \uB429\uB2C8\uB2E4.\\n\\n\uC9C0\uAE08\uAE4C\uC9C0\uC758 \uB0B4\uC6A9\uC744 \uC815\uB9AC\uD558\uBA74 \uB300\uB7B5 \uC544\uB798\uC640 \uAC19\uC740 \uBC29\uC2DD\uC73C\uB85C \uACF5\uACA9\uC744 \uC9C4\uD589\uD558\uBA74 \uB429\uB2C8\uB2E4.\\n\\n![](funny-smuggling-story-pt2/attack_flow.png)\\n\\n\uADF8\uB7FC \uC774\uC81C HAProxy\uAC00 \uC804\uB2EC\uBC1B\uC740 HTTP \uC694\uCCAD\uC774 400 Bad Request\uAC00 \uC548 \uB728\uBA74\uC11C \uB450 \uBC88\uC9F8 \uC694\uCCAD\uC758 CL \uD5E4\uB354\uC758 \uAC12\uACFC \uB2E4\uB974\uAC8C \uD558\uB824\uBA74 \uC5B4\uB5BB\uAC8C \uD574\uC57C \uD560\uAE4C\uC694?\\n\\nHAProxy\uAC00 \uD30C\uC2F1\uACFC\uC815\uC5D0\uC11C \uBE44\uC815\uC0C1 \uD5E4\uB354\uB97C \uC815\uC0C1\uC73C\uB85C \uB9CC\uB4E4\uBA74 \uB429\uB2C8\uB2E4.\\n\\nHAProxy\uB294 HTTP \uC694\uCCAD\uC744 \uD30C\uC2F1\uD560 \uB54C HTX\uB77C\uB294 \uAD6C\uC870\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4.\\n\\nHTX\uB294 \uD06C\uAC8C \uC2E4\uC81C \uB370\uC774\uD130\uAC00 \uB4E4\uC5B4\uC788\uB294 payload\uC640 \uD574\uB2F9 \uC815\uBCF4\uB97C \uC800\uC7A5\uD558\uB294 block\uC73C\uB85C \uB098\uB269\uB2C8\uB2E4.\\n\\nblock\uC5D0\uB294 \uC774 \uC815\uBCF4\uAC00 \uC5B4\uB5A4 payload\uC758 \uAC83\uC778\uC9C0 \uC8FC\uC18C\uB97C \uC800\uC7A5\uD558\uB294 \uBD80\uBD84\uACFC \uD574\uB2F9 payload\uC758 \uC815\uBCF4\uB97C \uC800\uC7A5\uD558\uB294 \uBD80\uBD84\uC73C\uB85C \uB098\uB269\uB2C8\uB2E4.\\n\\nHTX_BLOCK \uAD6C\uC870\uC758 \uB450 \uBA64\uBC84\uB294 \uBAA8\uB450 uint32 (4byte) \uC790\uB8CC\uD615\uC744 \uC4F0\uACE0 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n![](funny-smuggling-story-pt2/htx_t.png)\\n\\npayload\uC758 \uC815\uBCF4\uB97C \uC800\uC7A5\uD558\uB294 \uBD80\uBD84\uC744 \uBCF4\uBA74 \uD5E4\uB354\uC758 \uAE38\uC774\uB97C \uC800\uC7A5\uD558\uB294 \uACF5\uAC04\uC774 1byte\uC778 \uAC83\uC744 \uC54C \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n\uC815\uC0C1\uC801\uC778 \uD5E4\uB354 \uC911 1byte(256)\uC744 \uB118\uB294 \uAE38\uC774\uB97C \uAC00\uC9C0\uB294 \uAC83\uC740 \uC5C6\uAE30 \uB54C\uBB38\uC5D0 \uBB38\uC81C\uAC00 \uC5C6\uC5B4\uBCF4\uC785\uB2C8\uB2E4.\\n\\n\uC2E4\uC81C\uB85C \uC544\uB798\uC640 \uAC19\uC774 \uC8FC\uC11D\uB9CC \uB0A8\uACA8\uB450\uACE0 \uAE38\uC774 \uAC80\uC99D \uCF54\uB4DC\uAC00 \uC874\uC7AC\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.\\n\\n```c reference referenceLinkText=\\"View on GitHub\\"\\nhttps://github.com/haproxy/haproxy/blob/3d5f19e04d88e7c8f71cba4ea12e383c91de89f6/include/haproxy/htx.h#L464-L470\\n```\\n\\n\uC774\uCC98\uB7FC \uBBF8\uD761\uD55C \uAC80\uC99D\uC740 \uACF5\uACA9\uC5D0 \uC4F0\uC774\uB294 \uC88B\uC740 \uAC00\uC82F\uC774 \uB429\uB2C8\uB2E4. \\n\\nInteger Overflow\uB97C \uD1B5\uD574 \uC815\uC0C1 \uD5E4\uB354 + dummy \uAD6C\uC870\uC758 \uD5E4\uB354\uC5D0\uC11C \uC815\uC0C1 \uBD80\uBD84\uB9CC \uCC98\uB9AC\uD558\uB3C4\uB85D \uD558\uBA74 \uC6B0\uB9AC\uB294 \uBE44\uC815\uC0C1 \uD5E4\uB354\uB97C \uC815\uC0C1\uC73C\uB85C \uBCF4\uC774\uAC8C \uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\nHTX\uB97C \uD30C\uC2F1\uD560 \uB54C \uD5E4\uB354\uC758 \uAE38\uC774\uB294 \uAD6C\uBD84\uC790 `:` \uC55E\uAE4C\uC9C0\uB85C \uACC4\uC0B0\uB429\uB2C8\uB2E4.\\n\\n```http\\nPOST / HTTP/1.1\\nContent-Length0aaaa..255\uAC1C..aa: --- (1)\\nContent-Length: 4 --- (2)\\n\\nCLCL\\n```\\n\\n(1)\uC5D0\uC11C \uD5E4\uB354\uC758 \uAE38\uC774\uB294 270\uC785\uB2C8\uB2E4.\\n\\n\uADF8\uB7F0\uB370 270\uC740 `0b100001110` \uC778\uB370 \uACF5\uAC04\uC740 8bit\uB9CC \uD560\uB2F9\uB418\uC5B4 \uC788\uC73C\uBBC0\uB85C \uC55E\uC5D0 1\uC740 \uC9E4\uB824\uC11C `0b00001110` \uB9CC \uC800\uC7A5\uB418\uAC8C \uB429\uB2C8\uB2E4.\\n\\n\uADF8\uB807\uAC8C \uC870\uC791\uB41C \uAE38\uC774 14\uB9CC\uD07C \uC77D\uC73C\uBA74 \uC815\uC0C1 \uD5E4\uB354\uC778 `Content-Length`\uB85C \uBC14\uB00C\uAC8C \uB429\uB2C8\uB2E4.\\n\\n\\n\\n\uC55E\uC11C \uC124\uBA85\uD55C \uBD80\uBD84\uB4E4\uC744 \uC815\uB9AC\uD558\uBA74 \uC544\uB798\uC758 \uC21C\uC11C\uB85C Smuggling\uC774 \uBC1C\uC0DD\uD569\uB2C8\uB2E4.\\n\\n1. \uD574\uB2F9 \uD328\uD0B7\uC744 HAProxy\uAC00 \uBC1B\uC744 \uB54C\uB294 (1)\uC740 \uBE44\uC815\uC0C1 \uD5E4\uB354\uB85C \uCC98\uB9AC\uB418\uACE0 (2)\uB97C \uAE30\uC900\uC73C\uB85C \uCC98\uB9AC\\n\\n2. HTX \uAD6C\uC870\uB85C \uD30C\uC2F1\uD560 \uB54C Integer Overflow\uB85C \uC778\uD574 (1)\uC774 \uC815\uC0C1 \uD5E4\uB354\uB85C \uCC98\uB9AC\\n\\n3. HAProxy\uAC00 \uC6F9 \uC11C\uBC84\uC5D0 \uC804\uB2EC\uD560 \uB54C\uB294 (1)\uC774 \uD574\uB2F9 \uC694\uCCAD\uC774 \uB2E4\uC74C\uACFC \uAC19\uC774 \uBC14\uB00C\uC5B4 \uC804\uB2EC\\n   \\n   ```http\\n   POST / HTTP/1.1\\n   Content-Length:0 --- (1)\\n   \\n   CLCL\\n   ```\\n\\n4. Content-Length\uB9CC\uD07C \uCC98\uB9AC \uD6C4 \uB0A8\uC740 CLCL\uC774 \uB2E4\uC74C \uB9AC\uD018\uC2A4\uD2B8\uC5D0 \uC0BD\uC785\uB428\\n\\n\uC774 \uCDE8\uC57D\uC810\uC740 \uB2F9\uC5F0\uD788 \uC544\uB798\uC640 \uAC19\uC774 \uAE38\uC774 \uAC80\uC0AC\uB97C \uCD94\uAC00\uD558\uB294 \uBC29\uD5A5\uC73C\uB85C \uD328\uCE58\uB418\uC5C8\uC2B5\uB2C8\uB2E4.\\n\\n```diff\\n+ if (name.len > 255 || value.len > 1048575)\\n+     return NULL;\\n```\\n\\n\\n\\n### CL-TE + \uD30C\uC11C\uC758 \uC798\uBABB\uB41C \uCC98\uB9AC \uB85C\uC9C1 \uC774\uC6A9\uD558\uAE30\\n\\nTomcat\uC740 JSP\uB97C \uCC98\uB9AC\uD558\uB294 Web Application Server \uC785\uB2C8\uB2E4.\\n\\n\uC791\uB144 7\uC6D4\uC5D0 tomcat\uC5D0\uC11C CL-TE \uC720\uD615\uC758 HTTP Request Smuggling \uCDE8\uC57D\uC810\uC774 \uBC1C\uACAC\uB418\uC5C8\uC2B5\uB2C8\uB2E4.\\n\\n\uD574\uB2F9 \uBC84\uC83C\uC5D0\uC11C Client\uAC00 HTTP/1.0 \uC751\uB2F5\uB9CC \uBC1B\uC544\uB4E4\uC774\uB3C4\uB85D \uC120\uC5B8\uB418\uC5B4 \uC788\uC73C\uBA74 Tomcat\uC774 TE \uD5E4\uB354\uB97C \uBB34\uC2DC\uD558\uB294 \uB85C\uC9C1\uC774 \uC874\uC7AC\uD558\uC600\uACE0 \uACB0\uACFC\uC801\uC73C\uB85C \uC544\uB798\uC640 \uAC19\uC774 \uB3D9\uC791\uD558\uC600\uC2B5\uB2C8\uB2E4.\\n\\n![image-20220303173216629](funny-smuggling-story-pt2/cl_te_attack_flow.png)\\n\\n## \uB9C8\uCE58\uBA70\\n\\nHTTP Request Smuggling\uC740 \uCC98\uB9AC \uBC29\uC2DD\uC774 \uB3D9\uAE30\uD654\uB418\uC9C0 \uC54A\uC558\uB2E4\uACE0 \uD558\uC5EC HTTP Desync Attack\uC774\uB77C\uACE0\uB3C4 \uBD88\uB9BD\uB2C8\uB2E4. \\n\\nDEFCON \uB300\uD68C \uC608\uC120 \uBB38\uC81C\uB85C \uD574\uB2F9 \uCDE8\uC57D\uC810\uC744 \uC774\uC6A9\uD55C \uBB38\uC81C\uAC00 \uCD9C\uC81C\uB41C \uBC14 \uC788\uC73C\uB2C8 \uD480\uC5B4\uBCF4\uC2DC\uBA74 \uC774\uD574\uD558\uC2DC\uB294 \uB370 \uB3C4\uC6C0\uC774 \uB418\uC2E4 \uAC81\uB2C8\uB2E4.\\n\\n[uploooadit | OOO archive | DEF CON CTF](https://archive.ooo/c/uploooadit/351/)\\n\\n### Reference\\n\\n- https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2021-33037\\n- https://cve.mitre.org/cgi-bin/cvename.cgi?name=CVE-2021-40346\\n- https://github.com/haproxy/haproxy/commit/3b69886f7dcc3cfb3d166309018e6cfec9ce2c95#diff-8420c19f30c823a2c9cbe3ee5d35cf31550110b38fe767b620880f9cd82cecc8"},{"id":"/memo_tips","metadata":{"permalink":"/blog/memo_tips","source":"@site/blog/memo_tips.md","title":"\uC0AC\uC18C\uD55C \uD301 \uB4E4 \uC815\uB9AC","description":"nginx - fastapi \uAD6C\uC870\uC758 \uC11C\uBE44\uC2A4\uC5D0\uC11C \uC65C \uC778\uC9C0 \uD55C\uAE00 \uCC98\uB9AC\uAC00 \uC81C\uB300\uB85C \uB418\uC9C0 \uC54A\uC558\uB2E4.","date":"2022-02-18T00:00:00.000Z","tags":[{"inline":true,"label":"memo","permalink":"/blog/tags/memo"},{"inline":true,"label":"tip","permalink":"/blog/tags/tip"}],"readingTime":0.33,"hasTruncateMarker":true,"authors":[{"name":"SYRU","title":"security researcher","url":"https://github.com/l0vey0u","imageURL":"https://avatars.githubusercontent.com/u/30224688","key":"syru","page":null}],"frontMatter":{"title":"\uC0AC\uC18C\uD55C \uD301 \uB4E4 \uC815\uB9AC","authors":"syru","tags":["memo","tip"],"date":"2022-02-18T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\uC7AC\uBC0C\uB294 HTTP Request Smuggling \uC774\uC57C\uAE30 (2)","permalink":"/blog/funny-smuggling-story-pt2"},"nextItem":{"title":"\uC7AC\uBC0C\uB294 HTTP Request Smuggling \uC774\uC57C\uAE30 (1)","permalink":"/blog/funny-smuggling-story-pt1"}},"content":"nginx - fastapi \uAD6C\uC870\uC758 \uC11C\uBE44\uC2A4\uC5D0\uC11C \uC65C \uC778\uC9C0 \uD55C\uAE00 \uCC98\uB9AC\uAC00 \uC81C\uB300\uB85C \uB418\uC9C0 \uC54A\uC558\uB2E4.\\ncharset = utf8 \uC124\uC815\uC744 \uC8FC\uC5B4\uB3C4 \uD574\uACB0\uC774 \uB418\uC9C0 \uC54A\uC790\\n{/* truncate */}\\n### Base64 Encoding\\nURL \uC778\uCF54\uB529 \uD6C4 \uADF8 \uBB38\uC790\uC5F4\uC744 base64\uCC98\uB9AC\uD558\uC5EC \uC804\uB2EC\uD574\uC11C \uD574\uACB0\uD558\uC600\uB2E4.\\n```js\\nencoded_kr = window.btoa(unescape(encodeURLComponent(kr_str)))\\n```\\n\\n```python\\nfrom base64 import b64decode\\ndecoded_kr = b64decode(encoded_kr).decode()\\n```\\n\\n### \uB354 \uC54C\uC544\uBCF4\uC544\uC57C \uD560 \uC810\\nclient js \uC5D0\uC11C \uC804\uB2EC\uD558\uB294 \uC704\uCE58\uC5D0\uC120 \uD55C\uAE00\uC774 \uAE68\uC84C\uB294\uB370 fastapi\uC5D0\uC11C \uC804\uB2EC\uD558\uB294 \uBC29\uD5A5\uC73C\uB860 \uD55C\uAE00\uC774 \uC548 \uAE68\uC84C\uB2E4 js \uCABD\uC774 \uBB38\uC81C\uC600\uB098..?"},{"id":"/funny-smuggling-story-pt1","metadata":{"permalink":"/blog/funny-smuggling-story-pt1","source":"@site/blog/funny-smuggling-story-pt1.md","title":"\uC7AC\uBC0C\uB294 HTTP Request Smuggling \uC774\uC57C\uAE30 (1)","description":"\uC548\uB155\uD558\uC138\uC694 : ) \uC2DC\uB8E8\uC785\uB2C8\uB2E4.","date":"2022-02-06T18:00:00.000Z","tags":[{"inline":true,"label":"research","permalink":"/blog/tags/research"},{"inline":true,"label":"http","permalink":"/blog/tags/http"},{"inline":true,"label":"http smuggling","permalink":"/blog/tags/http-smuggling"}],"readingTime":2.42,"hasTruncateMarker":true,"authors":[{"name":"SYRU","title":"security researcher","url":"https://github.com/l0vey0u","imageURL":"https://avatars.githubusercontent.com/u/30224688","key":"syru","page":null}],"frontMatter":{"title":"\uC7AC\uBC0C\uB294 HTTP Request Smuggling \uC774\uC57C\uAE30 (1)","authors":"syru","tags":["research","http","http smuggling"],"date":"2022-02-06T18:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\uC0AC\uC18C\uD55C \uD301 \uB4E4 \uC815\uB9AC","permalink":"/blog/memo_tips"},"nextItem":{"title":"\uC6B0\uB9AC\uAC00 \uC54C\uACE0\uC788\uB294 Underflow\uB294 Underflow\uAC00 \uC544\uB2C8\uB2E4.","permalink":"/blog/memo_about_underflow"}},"content":"\uC548\uB155\uD558\uC138\uC694 : ) \uC2DC\uB8E8\uC785\uB2C8\uB2E4.\\n\\n\uC624\uB298\uC740 \uAC04\uB2E8\uD55C \uC6D0\uB9AC\uC9C0\uB9CC \uBD88\uD2B9\uC815 \uB2E4\uC218\uC5D0\uAC8C \uD53C\uD574\uB97C \uC904 \uC218 \uC788\uB294 \uACF5\uACA9\uAE30\uBC95\uC744 \uAC00\uC838\uC654\uC2B5\uB2C8\uB2E4.\\n\\n{/* truncate */}\\n\\n### \uACB0\uACFC\uBB3C\uC774 \uC81C \uC694\uCCAD\uACFC \uB2EC\uB77C\uC694\\n\\n\uC124\uBA85\uC744 \uC704\uD574 \uB77C\uBCA8\uAE30\uB97C \uAC00\uC838\uC654\uC2B5\uB2C8\uB2E4. \uC774 \uB77C\uBCA8\uAE30\uB294 \uBB38\uC7A5\uACFC \uAE38\uC774\uB97C \uC785\uB825\uD558\uBA74 \uAE38\uC774\uB9CC\uD07C \uC798\uB77C \uC90D\uB2C8\uB2E4.\\n\\n\uC7A5\uB09C\uAFB8\uB7EC\uAE30 \uC2DC\uB8E8\uAC00 \u201C\uC2DC\uB8E8\uBC18\u201D\uC774\uB77C\uB294 \uBB38\uC7A5\uC744 \uC785\uB825\uD574\uB193\uACE0 \uB450 \uAE00\uC790\uB9CC \uC785\uB825\uD588\uB2E4\uACE0 \uD558\uBA74 \uC5B4\uB5BB\uAC8C \uB420\uAE4C\uC694?\\n\\n![label printer image for prologue](funny-smuggling-story-pt1/label_printer_for_prologue.png)\\n\\n\uADF8\uB2E4\uC74C \uC785\uB825\uC774\uC5C8\uB358 \u201C\uBBFC\uCD08\uB2E8\u201D \uB77C\uBCA8\uC774 \u201C\uBC18\uBBFC\uCD08\u201D\uAC00 \uB418\uC5B4\uBC84\uB838\uC2B5\uB2C8\uB2E4...!\\n\\n\uC774\uB294 \uC2DC\uB8E8\uC758 \uC694\uCCAD\uC744 \uCC98\uB9AC\uD55C \uD6C4 \uB0A8\uC740 \u2018\uBC18\u2019\uC774\uB77C\uB294 \uAE00\uC790\uAC00 \uB2E4\uC74C \uC694\uCCAD\uC5D0 \uD3EC\uD568\uB418\uC5B4 \uBC1C\uC0DD\uD55C \uAC83\uC785\uB2C8\uB2E4.\\n\\n\uC774\uB7F0 \uC77C\uC774 \uC6F9 \uC11C\uBE44\uC2A4\uC5D0\uC11C\uB3C4 \uBC1C\uC0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC774\uBC88 \uAE00\uC5D0\uC11C\uB294 \uB098\uC758 \uC694\uCCAD\uC774 \uD0C0\uC778\uC5D0\uAC8C \uC601\uD5A5\uC744 \uC904 \uC218 \uC788\uB294 HTTP Request Smuggling\uC744 \uC54C\uC544\uBCF4\uACA0\uC2B5\uB2C8\uB2E4.\\n\\n## HTTP Request Smuggling\\n\\n> HTTP \uC694\uCCAD\uC5D0 \uB300\uD55C \uC77C\uAD00\uC131 \uC5C6\uB294 \uD574\uC11D\\n> \\n\\n[CWE-444: Inconsistent Interpretation of HTTP Requests (\'HTTP Request Smuggling\')](https://cwe.mitre.org/data/definitions/444.html)\\n\\n### \uB3D9\uC77C\uD55C TCP Connection\uC5D0\uC11C \uC5EC\uB7EC\uAC1C\uC758 HTTP Message\uAC00 \uCC98\uB9AC\uB41C \uC0AC\uC5F0\\n\\nHTTP \uD504\uB85C\uD1A0\uCF5C\uC740 TCP \uD1B5\uC2E0 \uC704\uC5D0\uC11C \uB3D9\uC791\uD569\uB2C8\uB2E4.\\n\\n(UDP\uB97C \uC0AC\uC6A9\uD558\uB294 HTTP 3\uB294 \uC774 \uAE00\uC5D0\uC120 \uC5B8\uAE09\uD558\uC9C0 \uC54A\uACA0\uC2B5\uB2C8\uB2E4.)\\n\\nTCP \uD1B5\uC2E0\uC740 \uC2E0\uB8B0\uD560 \uC218 \uC788\uB294 \uD1B5\uC2E0\uC744 \uC704\uD574 \uC5EC\uB7EC \uC815\uBCF4\uB97C \uACF5\uC720\uD558\uB294 3way handshake\uACFC\uC815\uC744 \uAC70\uCE69\uB2C8\uB2E4.\\n\\nHTTP \uD1B5\uC2E0\uC744 \uD560 \uB54C\uB9C8\uB2E4 TCP \uD1B5\uC2E0\uC744 \uC0C8\uB85C \uD574\uC57C \uD55C\uB2E4\uBA74 \uB2F9\uC5F0\uD788 \uADF8\uB9CC\uD07C handshake\uB3C4 \uD574\uC57C \uD558\uAC8C \uB429\uB2C8\uB2E4.\\n\\n\uC774 \uC2DC\uAC04\uC744 \uCD5C\uB300\uD55C \uC904\uC774\uAE30 \uC704\uD574 HTTP\uB294 \uAE30\uC874\uC5D0 \uB9CC\uB4E4\uC5B4\uC9C4 TCP \uD1B5\uC2E0\uC744 \uC0AC\uC6A9\uD558\uAC8C \uB418\uC5C8\uC2B5\uB2C8\uB2E4.\\n\\n### HTTP\uC5D0\uC11C Body \uC815\uBCF4\uB97C \uC5BB\uB294 \uBC29\uBC95\\n\\n[RFC \uBB38\uC11C](https://datatracker.ietf.org/doc/html/rfc7230#section-3.3.3)\uC5D0 \uB530\uB974\uBA74 Body\uC758 \uAE38\uC774\uB294 \uB2E4\uC74C \uADDC\uCE59\uC744 \uB530\uB985\uB2C8\uB2E4.\\n\\n- Transfer-Encoding \uD5E4\uB354\uAC00 \uC874\uC7AC\uD558\uACE0 chunked transfer coding\uC73C\uB85C \uC804\uB2EC\uB420 \uB54C transfer coding\uC774 data \uC804\uC1A1\uC774 \uB05D\uB0AC\uC74C\uC744 \uAC00\uB9AC\uD0AC \uB54C\uAE4C\uC9C0\uC758 \uAE38\uC774\uB85C \uACB0\uC815\\n- Transfer-Encoding \uD5E4\uB354\uAC00 \uC874\uC7AC\uD558\uC9C0 \uC54A\uACE0 \uC720\uD6A8\uD55C Content-Length \uD5E4\uB354\uAC00 \uC874\uC7AC\uD560 \uB54C \uD574\uB2F9 \uD5E4\uB354\uC758 \uAC12\uC73C\uB85C \uACB0\uC815\\n- Transfer-Encoding \uD5E4\uB354\uC640 Content-Length \uD5E4\uB354\uAC00 \uBAA8\uB450 \uC874\uC7AC\uD558\uBA74 Content-Length \uD5E4\uB354 \uBB34\uC2DC\\n- Content-Length \uD5E4\uB354\uAC00 \uC5EC\uB7EC \uAC1C \uC788\uC73C\uBA74 400 Bad Request \uCC98\uB9AC\\n\\n### \uB77C\uBCA8\uAE30\uAC00 \uC6F9 \uC11C\uBE44\uC2A4\uC600\uB2E4\uBA74\\n\\n\uB77C\uBCA8\uAE30 \uC774\uC57C\uAE30\uB97C \uC6F9 \uC11C\uBE44\uC2A4\uB85C \uD655\uC7A5 \uC2DC\uCF1C\uBCF4\uACA0\uC2B5\uB2C8\uB2E4.\\n\\n\uB77C\uBCA8\uAE30 \uC785\uB825\uC740 \uC644\uB8CC\uB97C \uB204\uB97C \uB54C\uAE4C\uC9C0 \uC785\uB825\uD558\uB2C8 Transfer-Encoding \uBC29\uC2DD\uC774 \uC5B4\uC6B8\uB9AC\uACE0 \uB77C\uBCA8 \uCEE4\uD130\uB294 \uC785\uB825\uBC1B\uC740 \uAE38\uC774\uB9CC\uD07C \uC790\uB974\uB2C8 Content-Length\uAC00 \uC5B4\uC6B8\uB9AC\uACA0\uB124\uC694\\n\\n\uB77C\uBCA8\uAE30\uC5D0 \uBB38\uC7A5\uC744 \uC785\uB825\uD558\uACE0 \uC790\uB974\uB294 \uACFC\uC815\uC740 \uC544\uB798\uC640 \uAC19\uC774 \uD45C\uD604\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n![packet diagram](funny-smuggling-story-pt1/packet_diagram.png)\\n\\n\uB77C\uBCA8 \uC694\uCCAD\uC5D0 \uB300\uD55C \uC751\uB2F5\uC740 \uC544\uB798\uC640 \uAC19\uC774 \uD45C\uD604\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n![simplified stream](funny-smuggling-story-pt1/packet_simplify.png)\\n\\n\uC774\uB807\uAC8C \uB41C \uC6D0\uC778\uC774 \uBB34\uC5C7\uC77C\uAE4C\uC694? \uC6B0\uC120 \uB3D9\uC77C\uD55C \uB77C\uBCA8\uCE74\uD2B8\uB9AC\uC9C0(TCP \uCEE4\uB125\uC158)\uC5D0\uC11C \uCC98\uB9AC\uB418\uC5C8\uACE0 \uB77C\uBCA8\uAE30\uC5D0\uC11C\uB294 \uBB38\uC790\uC5F4\uC758 \uB05D(Transfer-Encoding)\uC774 \uAE30\uC900\uC774\uC600\uC9C0\uB9CC \uB77C\uBCA8 \uCEE4\uD130\uC5D0\uC11C\uB294 \uAE38\uC774\uB85C \uC785\uB825\uD55C \uAC12(Content-Length)\uC774 \uAE30\uC900\uC774\uC600\uAE30 \uB54C\uBB38\uC785\uB2C8\uB2E4. \\n\\n\uB77C\uBCA8 \uCEE4\uD130\uB294 \uC55E\uC11C \uC124\uBA85\uB4DC\uB9B0 \uADDC\uCE59\uC744 \uC5B4\uAE34 \uC608\uC2DC\uB77C\uACE0 \uBCFC \uC218\uB3C4 \uC788\uACA0\uB124\uC694\\n\\n\uC774\uB7EC\uD55C \uBC29\uC2DD\uC73C\uB85C \uB2E4\uB978 \uC694\uCCAD\uC5D0 \uC0BD\uC785\uB418\uC5B4 \uD574\uB2F9 \uC694\uCCAD\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uAC8C \uD558\uAC70\uB098 \uC644\uC804\uD788 \uB2E4\uB978 \uC694\uCCAD\uC73C\uB85C \uBC14\uAFD4\uBC84\uB9B4 \uC218 \uC788\uB294 \uACF5\uACA9\uC774 \uBC14\uB85C **HTTP Request Smuggling**\uC785\uB2C8\uB2E4.\\n\\n\uC774 \uACF5\uACA9\uAE30\uBC95\uC740 \uC720\uD615\uC774 \uD06C\uAC8C \uB450 \uAC00\uC9C0\uB85C \uB098\uB269\uB2C8\uB2E4.\\n\\nContent-Length \uD5E4\uB354 \uC911\uBCF5 \uBB38\uC81C \uC774\uD558 CL-CL\uC774\uB77C \uBD80\uB974\uB294 \uC720\uD615\uACFC Transfer-Encoding, Content-Length \uD5E4\uB354 \uD63C\uB3D9 \uBB38\uC81C \uC774\uD558 CL-TE\uB77C\uACE0 \uBD80\uB974\uB294 \uC720\uD615\uC785\uB2C8\uB2E4.\\n\\n### \uADF8\uB0E5 \uD45C\uC900\uB9CC \uB530\uB974\uBA74 \uB418\uB294 \uAC83 \uC544\uB2CC\uAC00\uC694?\\n\\n\uB9DE\uC2B5\uB2C8\uB2E4. \uCC98\uB9AC\uD558\uB294 \uC8FC\uCCB4\uB4E4\uC774 \uBAA8\uB450 \uB3D9\uC77C\uD55C \uAE30\uC900\uC73C\uB85C \uCC98\uB9AC\uD558\uBA74 \uB429\uB2C8\uB2E4.\\n\\n\uD558\uC9C0\uB9CC \uCD5C\uADFC \uACF5\uACA9 \uC720\uD615\uC740 \uC694\uCCAD\uC744 \uD30C\uC2F1\uD560 \uB54C \uD2B9\uC815 \uD5E4\uB354\uB97C \uC778\uC2DD\uD558\uC9C0 \uBABB\uD558\uB3C4\uB85D \uD2B9\uC218\uBB38\uC790\uB97C \uC0BD\uC785\uD558\uAC70\uB098 \uB2E4\uB978 \uB0B4\uC6A9\uC73C\uB85C \uC778\uC2DD\uD558\uB3C4\uB85D Buffer Overflow \uAE30\uBC95\uC744 \uC0AC\uC6A9\uD558\uB294 \uB4F1 \uADDC\uCE59\uB9CC \uB530\uB77C\uC11C\uB294 \uB300\uC751\uD558\uAE30 \uC5B4\uB824\uC6B4 \uAC83\uC774 \uB9CE\uC2B5\uB2C8\uB2E4.\\n\\n\uD45C\uC900\uC744 \uB530\uB974\uB294 \uAC83 \uC678\uC5D0\uB3C4 \uAE30\uBCF8\uC801\uC778 \uAE38\uC774 \uAC80\uC99D\uC774\uB098 \uD2B9\uC218\uBB38\uC790 \uCC98\uB9AC\uB4F1\uC744 \uC2E0\uACBD\uC368\uC57C \uD569\uB2C8\uB2E4.\\n\\n## \uB9C8\uCE58\uBA70\\n\\n\uB2E4\uC74C \uD3EC\uC2A4\uD2B8\uC5D0\uC11C\uB294 \uC2E4\uC81C\uB85C \uCDE8\uC57D\uC810\uC774 \uBC1C\uC0DD\uD55C \uC0AC\uB840\uB97C \uACF5\uACA9 \uC720\uD615\uBCC4\uB85C \uB2E4\uB904\uBCF4\uACA0\uC2B5\uB2C8\uB2E4."},{"id":"/memo_about_underflow","metadata":{"permalink":"/blog/memo_about_underflow","source":"@site/blog/memo_about_underflow.md","title":"\uC6B0\uB9AC\uAC00 \uC54C\uACE0\uC788\uB294 Underflow\uB294 Underflow\uAC00 \uC544\uB2C8\uB2E4.","description":"\uC798 \uC54C\uB824\uC9C4 Underflow\uC758 \uC815\uC758","date":"2020-02-16T00:00:00.000Z","tags":[{"inline":true,"label":"memo","permalink":"/blog/tags/memo"},{"inline":true,"label":"term","permalink":"/blog/tags/term"},{"inline":true,"label":"underflow","permalink":"/blog/tags/underflow"}],"readingTime":0.36,"hasTruncateMarker":true,"authors":[{"name":"SYRU","title":"security researcher","url":"https://github.com/l0vey0u","imageURL":"https://avatars.githubusercontent.com/u/30224688","key":"syru","page":null}],"frontMatter":{"title":"\uC6B0\uB9AC\uAC00 \uC54C\uACE0\uC788\uB294 Underflow\uB294 Underflow\uAC00 \uC544\uB2C8\uB2E4.","authors":"syru","tags":["memo","term","underflow"],"date":"2020-02-16T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\uC7AC\uBC0C\uB294 HTTP Request Smuggling \uC774\uC57C\uAE30 (1)","permalink":"/blog/funny-smuggling-story-pt1"}},"content":"### \uC798 \uC54C\uB824\uC9C4 Underflow\uC758 \uC815\uC758\\n\uC790\uB8CC\uD615\uC774 \uC800\uC7A5\uD560 \uC218 \uC788\uB294 \uBC94\uC704\uB97C **\uB118\uC5B4\uC11C** \uCD5C\uC19F\uAC12 \uBCF4\uB2E4 \uC791\uC544\uC9C0\uBA74 \uCD5C\uB313\uAC12 \uBD80\uD130 \uB2E4\uC2DC \uC2DC\uC791\uB418\uB294 \uD604\uC0C1\\n{/* truncate */}\\n\\n### \uC774 \uC5ED\uC2DC Integer Overflow\\n\\n```\\n# 32bit\\n-2,147,483,648 - 1\\n= -2,147,483,648 + (~1)\\n\\n0,10000000,00000000,00000000,00000000(2)\\n0,11111111,11111111,11111111,11111111(2)\\n--------------------------------------\\n1,01111111,11111111,11111111,11111111(2)\\n\\noverflow \uBD80\uBD84 \uC81C\uC678 \\n= 2,147,483,648\\n```\\n\\n### \uADF8\uB7FC Underflow\uB294 \uBB34\uC5C7\uC778\uAC00?\\n\uBD80\uB3D9\uC18C\uC218\uC810\uC5D0\uC11C \uD45C\uD604 \uAC00\uB2A5 \uBC94\uC704\uBCF4\uB2E4 \uC791\uC740 0\uC5D0 \uAC00\uAE4C\uC6B4 \uC218\uAC00 0\uC774 \uB418\uB294 \uD604\uC0C1\\n\\n### Integer Underflow\\n\uC124\uBA85\uC5D0 \uD3B8\uC758\uC131\uC744 \uC704\uD574 Floating Underflow, Integer Underflow\uB85C \uAD6C\uBD84\uD558\uC5EC Underflow\uB97C \uC4F0\uAE30\uB3C4 \uD55C\uB2E4."}]}}')}}]);